pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a receiver that reverts on any incoming call
        Reverter reverter = new Reverter();

        // Set up the owner to call sendMoney
        address owner = address(this);
        vm.deal(owner, 1 ether);

        // fund the contract initially so sendMoney can send
        vm.deal(address(c), 0.5 ether);

        // Call sendMoney to the reverter, which will cause a revert
        // In the reference: fallback is triggered first (depositCount++), then sendMoney reverts
        // In the mutant: transfer reverts before fallback (no increment)
        try c.sendMoney(address(reverter), 1 wei, "") {
            // should not reach here
        } catch {
            // expected revert
        }

        // The reference version increments depositCount (1), the mutant does not (0)
        // Since the owner is the same, we can check the getter
        assertTrue(c.depositsCount() == 1);
    }
}

contract Reverter {
    receive() external payable {
        revert("I always revert");
    }
}

