        address target = address(0xdead);
        vm.deal(address(c), 0); // ensure no initial ether
        vm.deal(address(this), 1 ether); // fund caller
        vm.prank(address(this));
        // Call sendMoney with 1 wei to a reverting target (no code, will revert)
