import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a contract that rejects ether in its fallback
        Rejector rejector = new Rejector();

        // Fund the owner (default is address(this) since owner = payable(msg.sender))
        vm.deal(address(this), 1 ether);

        // Send 1 wei to the rejector via sendMoney
        c.sendMoney(address(rejector), 1 wei, "");

        // Now attempt to withdrawAll - this will fail on reference but succeed on mutant
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract fails (ok == false), mutant succeeds (ok == true)
        assertTrue(ok == true, "Reference should revert, mutant should pass");
    }
}

contract Rejector {
    fallback() external payable {
        revert("I reject ether");
    }
    receive() external payable {
        revert("I reject ether");
    }
}

