    function testRegression_property() public {
        address blackhole = address(0xdead);
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        c.sendMoney(blackhole, 1 ether, "");
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        try c.withdrawAll() {
            // mutant succeeds
        } catch {
            // reference reverts
        }
