    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Deploy a helper contract to reenter withdraw
        ReenterHelper helper = new ReenterHelper(address(c));

        // Prank as a non-owner address (e.g., address(0x1))
        address attacker = address(0x1);
        vm.deal(attacker, 0.5 ether);
        vm.prank(attacker);

        // Call sendMoney to trigger reentrant withdraw of 0.1 ether
        try c.sendMoney{value: 0.5 ether}(address(helper), 0.1 ether, abi.encodeWithSignature("reenter()")) {
            // sendMoney succeeded (reference case)
        } catch {
            // sendMoney reverted (buggy case)
        }

        // Assert: reference contract's balance is 0.9 ether, buggy contract's balance is 1 ether
        assertTrue(address(c).balance == 0.9 ether || address(c).balance == 1 ether);
        // Explicitly: reference holds (0.9 ether), bug breaks (1 ether)
        assertTrue(address(c).balance == 0.9 ether ? true : false);
    }
}

contract ReenterHelper {
    C public c;
    constructor(address _c) { c = C(_c); }
    fallback() external payable {
        c.withdraw(msg.value);
    }
    function reenter() external payable {
        c.withdraw(msg.value);
    }
